package com.denissa.wildernessloadouts;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

@Singleton
public class BankLayoutService
{
	static final String GENERATED_TAG = "_wilderness_loadouts_generated";

	private final Client client;
	private final ItemManager itemManager;
	private final PluginManager pluginManager;
	private final BankTagsPlugin bankTagsPlugin;
	private final BankTagsService bankTagsService;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;

	@Inject
	BankLayoutService(
		Client client,
		ItemManager itemManager,
		PluginManager pluginManager,
		BankTagsPlugin bankTagsPlugin,
		BankTagsService bankTagsService,
		TagManager tagManager,
		LayoutManager layoutManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.pluginManager = pluginManager;
		this.bankTagsPlugin = bankTagsPlugin;
		this.bankTagsService = bankTagsService;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
	}

	public boolean isBankTagsEnabled()
	{
		return pluginManager.isPluginEnabled(bankTagsPlugin) && pluginManager.isPluginActive(bankTagsPlugin);
	}

	public boolean isGeneratedLayoutOpen()
	{
		return GENERATED_TAG.equals(bankTagsService.getActiveTag());
	}

	public void enableBankTags() throws PluginInstantiationException
	{
		if (!pluginManager.isPluginEnabled(bankTagsPlugin))
		{
			pluginManager.setPluginEnabled(bankTagsPlugin, true);
		}
		if (!pluginManager.isPluginActive(bankTagsPlugin))
		{
			try
			{
				pluginManager.startPlugin(bankTagsPlugin);
			}
			catch (PluginInstantiationException exception)
			{
				pluginManager.setPluginEnabled(bankTagsPlugin, false);
				throw exception;
			}
		}
	}

	public String showLoadout(LoadoutResult result)
	{
		if (client.getItemContainer(InventoryID.BANK) == null
			|| client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null)
		{
			return "Open your bank before showing the virtual layout.";
		}

		clearGeneratedLayout();
		Layout layout = new Layout(GENERATED_TAG);
		for (GearSlot slot : GearSlot.values())
		{
			GearItem item = result.getSelectedItem(slot);
			if (item == null || item.isEmpty())
			{
				continue;
			}

			int itemId = itemManager.canonicalize(item.getItemId());
			tagManager.addTag(itemId, GENERATED_TAG, false);
			layout.setItemAtPos(itemId, slot.getBankLayoutPosition());
		}

		layoutManager.saveLayout(layout);
		tagManager.setHidden(GENERATED_TAG, true);
		bankTagsService.openBankTag(GENERATED_TAG, BankTagsService.OPTION_HIDE_TAG_NAME);
		return null;
	}

	public void clearGeneratedLayout()
	{
		if (GENERATED_TAG.equals(bankTagsService.getActiveTag()))
		{
			bankTagsService.closeBankTag();
		}
		tagManager.removeTag(GENERATED_TAG);
		layoutManager.removeLayout(GENERATED_TAG);
	}
}

