package com.denissa.wildernessloadouts;

public enum DefenceFocus
{
	OVERALL("Best Overall Defence")
	{
		@Override
		public double score(GearItem item)
		{
			return (item.getMagicDefence() + item.getRangedDefence() + item.getMeleeDefence()) / 3.0;
		}
	},
	MAGIC("Best Magic Defence")
	{
		@Override
		public double score(GearItem item)
		{
			return item.getMagicDefence();
		}
	},
	RANGED("Best Ranged Defence")
	{
		@Override
		public double score(GearItem item)
		{
			return item.getRangedDefence();
		}
	},
	MELEE("Best Melee Defence")
	{
		@Override
		public double score(GearItem item)
		{
			return item.getMeleeDefence();
		}
	};

	private final String displayName;

	DefenceFocus(String displayName)
	{
		this.displayName = displayName;
	}

	public abstract double score(GearItem item);

	@Override
	public String toString()
	{
		return displayName;
	}
}

