package com.denissa.wildernessloadouts;

import java.util.Objects;

public final class GearItem
{
	private final int itemId;
	private final String name;
	private final GearSlot slot;
	private final int stabDefence;
	private final int slashDefence;
	private final int crushDefence;
	private final int magicDefence;
	private final int rangedDefence;
	private final LossProfile lossProfile;
	private final boolean twoHanded;

	public GearItem(
		int itemId,
		String name,
		GearSlot slot,
		int stabDefence,
		int slashDefence,
		int crushDefence,
		int magicDefence,
		int rangedDefence,
		LossProfile lossProfile,
		boolean twoHanded)
	{
		this.itemId = itemId;
		this.name = Objects.requireNonNull(name);
		this.slot = Objects.requireNonNull(slot);
		this.stabDefence = stabDefence;
		this.slashDefence = slashDefence;
		this.crushDefence = crushDefence;
		this.magicDefence = magicDefence;
		this.rangedDefence = rangedDefence;
		this.lossProfile = Objects.requireNonNull(lossProfile);
		this.twoHanded = twoHanded;
	}

	/**
	 * Convenience constructor retained for optimizer fixtures and simple market
	 * candidates. Production item discovery supplies a full loss profile.
	 */
	public GearItem(
		int itemId,
		String name,
		GearSlot slot,
		int stabDefence,
		int slashDefence,
		int crushDefence,
		int magicDefence,
		int rangedDefence,
		long riskValue,
		boolean twoHanded,
		boolean priceKnown)
	{
		this(
			itemId,
			name,
			slot,
			stabDefence,
			slashDefence,
			crushDefence,
			magicDefence,
			rangedDefence,
			priceKnown ? LossProfile.estimate(riskValue) : LossProfile.unknown(),
			twoHanded);
	}

	public static GearItem empty(GearSlot slot)
	{
		return new GearItem(-1, "Empty", slot, 0, 0, 0, 0, 0, LossProfile.estimate(0), false);
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public GearSlot getSlot()
	{
		return slot;
	}

	public int getStabDefence()
	{
		return stabDefence;
	}

	public int getSlashDefence()
	{
		return slashDefence;
	}

	public int getCrushDefence()
	{
		return crushDefence;
	}

	public int getMagicDefence()
	{
		return magicDefence;
	}

	public int getRangedDefence()
	{
		return rangedDefence;
	}

	public LossProfile getLossProfile()
	{
		return lossProfile;
	}

	public boolean isTwoHanded()
	{
		return twoHanded;
	}

	public boolean isEmpty()
	{
		return itemId < 0;
	}

	public double getMeleeDefence()
	{
		return (stabDefence + slashDefence + crushDefence) / 3.0;
	}
}

