		JPanel actions = new JPanel(new GridLayout(0, 1, 0, 4));
		actions.setBackground(ColorScheme.DARK_GRAY_COLOR);
		long excludedItems = ownedGear.stream()
			.filter(item -> !item.getLossProfile().isAutoEligible())
			.count();
		if (excludedItems > 0)
		{
			String itemLabel = excludedItems == 1 ? "item" : "items";
			JLabel note = new JLabel(excludedItems + " owned " + itemLabel + " unavailable");
			note.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);
			note.setToolTipText(UNAVAILABLE_ITEMS_TOOLTIP);

			JLabel info = new JLabel("ⓘ");
			info.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);
			info.setHorizontalAlignment(SwingConstants.CENTER);
			info.setPreferredSize(new Dimension(18, 18));
			info.setToolTipText(UNAVAILABLE_ITEMS_TOOLTIP);

			JPanel unavailableNote = new JPanel(new BorderLayout(4, 0));
			unavailableNote.setBackground(ColorScheme.DARK_GRAY_COLOR);
			unavailableNote.add(note, BorderLayout.CENTER);
			unavailableNote.add(info, BorderLayout.EAST);
			actions.add(unavailableNote);
		}
		if (result.hasNonMonetaryBurdenSelected())
		{
			JLabel warning = new JLabel(
				"<html>Selected items have charges or reacquisition work not included in GP risk.</html>");
			warning.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);
			actions.add(warning);
		}
		actions.add(showInBankButton);
		resultPanel.add(actions, BorderLayout.SOUTH);

		resultPanel.revalidate();
		resultPanel.repaint();
	}

	private JPanel buildProtectedPanel()
	{
		ButtonGroup group = new ButtonGroup();
		group.add(protectedNone);
		group.add(protectedOne);
		group.add(protectedThree);
		group.add(protectedFour);
		JPanel panel = new JPanel(new GridLayout(1, 4));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.add(protectedNone);
		panel.add(protectedOne);
		panel.add(protectedThree);
		panel.add(protectedFour);
		return panel;
	}

	private JPanel buildSlotControls()
	{
		JPanel panel = new JPanel(new GridLayout(0, 2, 2, 0));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (GearSlot slot : GearSlot.values())
		{
			JCheckBox checkBox = new JCheckBox(slot.getDisplayName(), true);
			checkBox.setToolTipText("Unchecked forces this slot empty");
			checkBox.addActionListener(event ->
			{
				if (updatingSlotControls)
				{
					return;
				}
				slotSelections.put(slot, checkBox.isSelected()
					? LoadoutSlotSelection.auto()
					: LoadoutSlotSelection.empty());
				requestRecalculate();
			});
			slotCheckBoxes.put(slot, checkBox);
			panel.add(checkBox);
		}
		return panel;
	}

	private JButton buildResultButton(LoadoutRequest request, LoadoutResult result, GearSlot slot)
	{
		GearItem item = result.getSelectedItem(slot);
		boolean protectedItem = result.isProtected(slot);
		boolean locked = request.getSlotSelection(slot).getState() == SlotState.LOCKED;
		String markers = (protectedItem ? "★ " : "") + (locked ? "[LOCK] " : "");
		String name = item == null || item.isEmpty() ? "Empty" : shorten(item.getName(), 18);

		JButton button = new JButton(
			"<html><center>" + escapeHtml(slot.getDisplayName()) + "<br>"
				+ escapeHtml(markers + name) + "</center></html>");
		button.setPreferredSize(new Dimension(96, 68));
		button.setVerticalTextPosition(SwingConstants.BOTTOM);
		button.setHorizontalTextPosition(SwingConstants.CENTER);
		button.setBorder(BorderFactory.createLineBorder(
			protectedItem ? ColorScheme.BRAND_ORANGE : (locked ? LOCKED_COLOR : ColorScheme.MEDIUM_GRAY_COLOR),
			protectedItem || locked ? 2 : 1));
		button.setToolTipText(item == null || item.isEmpty()
			? buildEmptySlotTooltip(slot)
			: buildItemTooltip(item, result.getFocus()));
		button.addActionListener(event -> showAlternatives(slot));
		if (item != null && !item.isEmpty())
		{
			itemManager.getImage(item.getItemId()).addTo(button);
		}
		return button;
	}

	private void showAlternatives(GearSlot slot)
	{
		DefenceFocus focus = (DefenceFocus) focusSelector.getSelectedItem();
		int currentItemId = currentSelectionId(slot);
		List<GearItem> candidates = buildAlternatives(latestOwnedGear, slot, focus, currentItemId);

		DefaultListModel<GearItem> model = new DefaultListModel<>();
		for (GearItem candidate : candidates)
		{
			model.addElement(candidate);
		}
		JList<GearItem> list = new JList<>(model);
		list.setCellRenderer(new AlternativeRenderer(focus));
		list.setVisibleRowCount(Math.min(6, Math.max(1, model.size())));
		if (!model.isEmpty())
		{
			int selectedIndex = Math.max(0, indexOfItem(candidates, currentItemId));
			list.setSelectedIndex(selectedIndex);
			list.ensureIndexIsVisible(selectedIndex);
		}

		Object[] options = {"Lock selected", "Auto", "Empty", "Cancel"};
		int choice = JOptionPane.showOptionDialog(
			this,
			new JScrollPane(list),
			slot.getDisplayName() + " alternatives",
			JOptionPane.DEFAULT_OPTION,
			JOptionPane.PLAIN_MESSAGE,
			null,
			options,
			options[0]);

		if (choice == 0)
		{
			GearItem selected = list.getSelectedValue();
			if (selected == null)
			{
				showStatus("No owned item is available to lock in that slot.", true);
				return;
			}
			if (!selected.getLossProfile().isAutoEligible())
			{
				showStatus(
					selected.getName() + " is excluded: "
						+ selected.getLossProfile().getEligibilityPolicy().getExclusionReason(),
					true);
				return;
			}
			setSlotSelection(slot, LoadoutSlotSelection.locked(selected.getItemId()));
		}
		else if (choice == 1)
		{
			setSlotSelection(slot, LoadoutSlotSelection.auto());
		}
		else if (choice == 2)
		{
			setSlotSelection(slot, LoadoutSlotSelection.empty());
		}
	}

	/**
	 * The slot's alternatives, ranked eligible-first then by focus score. Capped at
	 * ALTERNATIVE_LIMIT, except that the slot's current item is always present: it is
	 * what the dialog preselects, and hiding it would let a confirm silently relock
	 * the slot to a different item.
	 */
	static List<GearItem> buildAlternatives(
		List<GearItem> ownedGear,
		GearSlot slot,
		DefenceFocus focus,
		int currentItemId)
	{
		List<GearItem> candidates = new ArrayList<>();
		for (GearItem item : ownedGear)
		{
			if (item.getSlot() == slot)
			{
				candidates.add(item);
			}
		}
		candidates.sort(Comparator
			.comparing((GearItem item) -> !item.getLossProfile().isAutoEligible())
			.thenComparing(Comparator
			.comparingDouble((GearItem item) -> focus.score(item)).reversed()
			.thenComparingLong(item -> item.getLossProfile().getCostIfUnprotected())
			.thenComparingInt(GearItem::getItemId)));
		if (candidates.size() <= ALTERNATIVE_LIMIT)
		{
			return candidates;
		}

		int currentIndex = indexOfItem(candidates, currentItemId);
		List<GearItem> visible = new ArrayList<>(candidates.subList(0, ALTERNATIVE_LIMIT));
		if (currentIndex >= ALTERNATIVE_LIMIT)
		{
			visible.add(candidates.get(currentIndex));
		}
		return visible;
	}

	private int currentSelectionId(GearSlot slot)
	{
		LoadoutSlotSelection selection = slotSelections.get(slot);
		if (selection.getState() == SlotState.LOCKED)
		{
			return selection.getLockedItemId();
		}
		GearItem selected = latestResult == null ? null : latestResult.getSelectedItem(slot);
		return selected == null || selected.isEmpty() ? -1 : selected.getItemId();
	}

	private static int indexOfItem(List<GearItem> items, int itemId)
	{
		for (int i = 0; i < items.size(); i++)
		{
			if (items.get(i).getItemId() == itemId)
			{
				return i;
			}
		}
		return -1;
	}

	private void setSlotSelection(GearSlot slot, LoadoutSlotSelection selection)
	{
		slotSelections.put(slot, selection);
		updatingSlotControls = true;
		slotCheckBoxes.get(slot).setSelected(selection.getState() != SlotState.EMPTY);
		updatingSlotControls = false;
		requestRecalculate();
	}

	private void calculate()
	{
		if (!bankAvailable)
		{
			showStatus("Open your bank once to scan your gear.", true);
			return;
		}
		try
		{
			listener.onCalculate(buildRequest());
		}
		catch (IllegalArgumentException exception)
		{
			showStatus(exception.getMessage(), true);
		}
	}

	private void requestRecalculate()
	{
		if (bankAvailable)
		{
			recalculationTimer.restart();
		}
	}

	private LoadoutRequest buildRequest()
	{
		DefenceFocus focus = (DefenceFocus) focusSelector.getSelectedItem();
		int protectedLimit = protectedNone.isSelected()
			? 0
			: (protectedOne.isSelected() ? 1 : (protectedFour.isSelected() ? 4 : 3));
		long budget = RiskBudgetParser.parse(riskField.getText());
		return new LoadoutRequest(focus, protectedLimit, budget, slotSelections);
	}

	private static JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	private static JLabel detailLabel(String label, String value)
	{
		JLabel result = new JLabel(label + ": " + value);
		result.setForeground(ColorScheme.TEXT_COLOR);
		return result;
	}

	private static String buildItemTooltip(GearItem item, DefenceFocus focus)
	{
		if (item == null || item.isEmpty())
		{
			return "Click to choose Auto, Empty, or lock an owned alternative";
		}
		return item.getName()
			+ " | " + focus + ": " + formatScore(focus.score(item))
			+ " | Magic " + item.getMagicDefence()
			+ " | Ranged " + item.getRangedDefence()
			+ " | Melee " + formatScore(item.getMeleeDefence())
			+ " | " + formatPrice(item)
			+ formatProtectedLoss(item.getLossProfile())
			+ " | " + item.getLossProfile().getSource();
	}

	private String buildEmptySlotTooltip(GearSlot slot)
	{
		long eligible = latestOwnedGear.stream()
			.filter(item -> item.getSlot() == slot && item.getLossProfile().isAutoEligible())
			.count();
		long excluded = latestOwnedGear.stream()
			.filter(item -> item.getSlot() == slot && !item.getLossProfile().isAutoEligible())
			.count();
		if (eligible == 0 && excluded > 0)
		{
			return excluded + " owned alternative(s) excluded by the loss policy; click for details";
		}
		return "Click to choose Auto, Empty, or lock an owned alternative";
	}

	private static String formatScore(double value)
	{
		if (Math.abs(value - Math.rint(value)) < 0.0001)
		{
			return String.format(Locale.ENGLISH, "%.0f", value);
		}
		return String.format(Locale.ENGLISH, "%.1f", value);
	}

	private static String formatSigned(double value)
	{
		return (value >= 0 ? "+" : "") + formatScore(value);
	}

	private static String formatGp(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}

	private static String formatPrice(GearItem item)
	{
		LossProfile profile = item.getLossProfile();
		if (!profile.isAutoEligible())
		{
			return "excluded: " + profile.getEligibilityPolicy().getExclusionReason();
		}
		String cost = formatGp(profile.getCostIfUnprotected());
		String displayedCost = profile.getConfidence() == LossProfile.Confidence.MARKET_ESTIMATE
			? "~" + cost
			: cost;
		String value;
		if (!profile.canBeProtected())
		{
			value = "always lost " + displayedCost;
		}
		else if (profile.getReacquisitionMethod() == LossProfile.ReacquisitionMethod.MARKET)
		{
			value = displayedCost;
		}
		else
		{
			value = profile.getReacquisitionMethod().getDisplayName() + " " + displayedCost;
		}
		if (profile.hasNonMonetaryBurden())
		{
			value += "; " + profile.getNonMonetaryBurden().getDisplayName();
		}
		return value;
	}

	private static String formatProtectedLoss(LossProfile profile)
	{
		if (!profile.canBeProtected() || profile.getCostIfProtected() <= 0)
		{
			return "";
		}
		return " | protected loss " + formatGp(profile.getCostIfProtected());
	}

	private static String shorten(String value, int maxLength)
	{
		return value.length() <= maxLength ? value : value.substring(0, maxLength - 1) + "…";
	}

	private static String escapeHtml(String value)
	{
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	public interface Listener
	{
		void onCalculate(LoadoutRequest request);

		void onShowInBank();
	}

	private static final class AlternativeRenderer extends JPanel implements ListCellRenderer<GearItem>
	{
		private final DefenceFocus focus;
		private final JLabel name = new JLabel();
		private final JLabel details = new JLabel();

		private AlternativeRenderer(DefenceFocus focus)
		{
			super(new GridLayout(0, 1));
			this.focus = focus;
			setBorder(new EmptyBorder(4, 4, 4, 4));
			add(name);
			add(details);
		}

		@Override
		public Component getListCellRendererComponent(
			JList<? extends GearItem> list,
			GearItem item,
			int index,
			boolean selected,
			boolean cellHasFocus)
		{
			name.setText(item.getName());
			name.setForeground(Color.WHITE);
			details.setText(
				"Score " + formatScore(focus.score(item))
					+ " | M " + item.getMagicDefence()
					+ " R " + item.getRangedDefence()
					+ " Melee " + formatScore(item.getMeleeDefence())
					+ " | " + formatPrice(item)
					+ formatProtectedLoss(item.getLossProfile()));
			details.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			setBackground(selected ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			return this;
		}
	}
}

